   468→                            className="h-5 w-5 text-sidebar-foreground/50 hover:text-sidebar-foreground"
   469→                            onClick={() => {
   470→                              handleConfigureWorkspace(activeWorkspaceId);
   471→                            }}
   472→                          >
   473→                            <Settings className="h-3.5 w-3.5" />
   474→                          </Button>
   475→                        </TooltipTrigger>
   476→                        <TooltipContent side="right">
   477→                          {t("workspace.configure")}
   478→                        </TooltipContent>
   479→                      </Tooltip>
   480→                      <Tooltip>
   481→                        <TooltipTrigger asChild>
   482→                          <Button
   483→                            variant="ghost"
   484→                            size="icon"
   485→                            className="h-5 w-5 text-sidebar-foreground/50 hover:text-sidebar-foreground"
   486→                            onClick={() => {
   487→                              openWorkspaceHome(activeWorkspaceId);
   488→                            }}
   489→                          >
   490→                            <Home className="h-3.5 w-3.5" />
   491→                          </Button>
   492→                        </TooltipTrigger>
   493→                        <TooltipContent side="right">
   494→                          {t("sidebar.workspaceHome")}
   495→                        </TooltipContent>
   496→                      </Tooltip>
   497→                    </div>
   498→                  }
   499→                >
   500→                  <nav className="flex flex-col gap-1">
   501→                    {workspaceNavItems.map((item) => (
   502→                      <WorkspaceNavItemComponent
   503→                        key={item.path}
   504→                        item={item}
   505→                        workspaceId={activeWorkspaceId}
   506→                        collapsed={collapsed}
   507→                        onNavigate={handleWorkspaceNavClick}
   508→                      />
   509→                    ))}
   510→                  </nav>
   511→                </SidebarSection>
   512→              )}
   513→
   514→              {/* Creator Section (only when authenticated) */}
   515→              {isAuthenticated && (
   516→                <SidebarSection
   517→                  title={t("creator.title")}
   518→                  collapsible
   519→                  defaultOpen
   520→                >
   521→                  <nav className="flex flex-col gap-1">
   522→                    {creatorNav.map((item) => (
   523→                      <NavItemComponent key={item.href} item={item} collapsed={collapsed} onNavigate={handleGlobalNavClick} />
   524→                    ))}
   525→                  </nav>
   526→                </SidebarSection>
   527→              )}
   528→            </div>
   529→          )}
   530→        </ScrollArea>
   531→
   532→        {/* Bottom Navigation & New Task */}
   533→        {collapsed ? (
   534→          <div className="pb-2 flex flex-col">
   535→            <SidebarBottomDrawer collapsed />
   536→            <WakeWordTaskButton
   537→              collapsed
   538→              onCreateTask={openChatPopup}
   539→              disabled={!activeWorkspace}
   540→            />
   541→          </div>
   542→        ) : (
   543→          <div className="pb-2 px-2">
   544→            <SidebarBottomDrawer collapsed={false} />
   545→            <WakeWordTaskButton
   546→              collapsed={false}
   547→              onCreateTask={openChatPopup}
   548→              disabled={!activeWorkspace}
   549→            />
   550→          </div>
   551→        )}
   552→
   553→        {/* Create Task Dialog */}
   554→        <CreateTaskDialog
   555→          open={isCreateTaskOpen}
   556→          onOpenChange={setIsCreateTaskOpen}
   557→          onSubmit={handleCreateTask}
   558→          isSubmitting={createTaskMutation.isPending}
   559→          availableAgents={agents.map((a: AgentInfo) => ({
   560→            id: a.id,
   561→            name: a.name,
   562→            description: a.description,
   563→            executorType: a.executor_type,
   564→          }))}
   565→          availableModels={models
   566→            .filter((m: WorkspaceModel) => m.is_available)
   567→            .map((m: WorkspaceModel) => ({
   568→              id: m.id,
   569→              name: m.name,
   570→              provider: m.provider_id,
   571→              provider_id: m.provider_id,
   572→            }))}
   573→          isLoadingOptions={isLoadingAgents || isLoadingModels}
   574→        />
   575→
   576→        {/* Add Workspace Modal */}
   577→        <AddWorkspaceModal
   578→          open={isAddWorkspaceModalOpen}
   579→          onOpenChange={setIsAddWorkspaceModalOpen}
   580→        />
   581→
   582→        {/* Delete Workspace Confirmation Dialog */}
   583→        <AlertDialog
   584→          open={!!workspaceToDelete}
   585→          onOpenChange={(open) => !open && setWorkspaceToDelete(null)}
   586→        >
   587→          <AlertDialogContent>
   588→            <AlertDialogHeader>
   589→              <AlertDialogTitle>{t("workspace.deleteConfirmTitle")}</AlertDialogTitle>
   590→              <AlertDialogDescription>
   591→                {t("workspace.deleteConfirmDescription", { name: workspaceToDelete?.name })}
   592→              </AlertDialogDescription>
   593→            </AlertDialogHeader>
   594→            <AlertDialogFooter>
   595→              <AlertDialogCancel disabled={isDeleting}>
   596→                {t("common.cancel")}
   597→              </AlertDialogCancel>
   598→              <AlertDialogAction
   599→                onClick={handleDeleteWorkspace}
   600→                disabled={isDeleting}
   601→                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
   602→              >
   603→                {isDeleting ? t("common.deleting") : t("common.delete")}
   604→              </AlertDialogAction>
   605→            </AlertDialogFooter>
   606→          </AlertDialogContent>
   607→        </AlertDialog>
   608→
   609→        {/* Workspace Settings Dialog */}
   610→        <WorkspaceSettingsDialog
   611→          open={!!workspaceToConfig}
   612→          onOpenChange={(open) => !open && setWorkspaceToConfig(null)}
   613→          workspaceId={workspaceToConfig}
   614→        />
   615→      </aside>
   616→    </TooltipProvider>
   617→  );
   618→}
   619→
   620→interface NavItemComponentProps {
   621→  item: NavItem;
   622→  collapsed: boolean;
   623→  onNavigate?: (href: string, name: string, icon: IconData) => void;
   624→}
   625→
   626→function NavItemComponent({ item, collapsed, onNavigate }: NavItemComponentProps) {
   627→  const { t } = useTranslation();
   628→  const location = useLocation();
   629→  const title = t(item.titleKey);
   630→
   631→  // Check if this item or any of its children are active
   632→  // This ensures /mcp-services is highlighted when on /mcp-services/dashboard etc.
   633→  const isActiveOrChild = location.pathname === item.href ||
   634→    location.pathname.startsWith(item.href + "/");
   635→
   636→  const iconName = getGlobalNavIconName(item.href);
   637→
   638→  const handleClick = () => {
   639→    if (onNavigate) {
   640→      onNavigate(item.href, title, { type: "lucide", value: iconName });
   641→    }
   642→  };
   643→
   644→  // Collapsed view - use unified SidebarIconButton component with centering wrapper
   645→  if (collapsed) {
   646→    return (
   647→      <div className="grid place-items-center w-full">
   648→        <SidebarIconButton
   649→          icon={<item.icon className="h-4 w-4" />}
   650→          tooltip={title}
   651→          onClick={handleClick}
   652→        />
   653→      </div>
   654→    );
   655→  }
   656→
   657→  // Expanded view - full link with text
   658→  return (
   659→    <button
   660→      type="button"
   661→      onClick={handleClick}
   662→      className={cn(
   663→        "group relative flex items-center gap-3 px-2 py-2 rounded-lg text-sm w-full text-left",
   664→        "transition-all duration-200",
   665→        isActiveOrChild
   666→          ? [
   667→              "bg-sidebar-accent text-sidebar-accent-foreground font-medium",
   668→              "before:absolute before:left-0 before:top-1/2 before:-translate-y-1/2",
   669→              "before:h-6 before:w-1 before:rounded-r-full before:bg-primary",
   670→            ]
   671→          : [
   672→              "text-sidebar-foreground/70",
   673→              "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
   674→            ]
   675→      )}
   676→    >
   677→      <item.icon
   678→        className={cn(
   679→          "h-4 w-4 shrink-0 transition-colors duration-200",
   680→          "group-hover:text-primary"
   681→        )}
   682→      />
   683→      <span>{title}</span>
   684→    </button>
   685→  );
   686→}
   687→
   688→function getGlobalNavIconName(href: string): string {
   689→  switch (href) {
   690→    case "/publish":
   691→      return "upload";
   692→    case "/my-packages":
   693→      return "package-search";
   694→    case "/analytics":
   695→      return "bar-chart-3";
   696→    case "/documents":
   697→      return "file-text";
   698→    case "/settings":
   699→      return "settings";
   700→    case "/devices/pair":
   701→      return "smartphone";
   702→    case "/mcp-services/dashboard":
   703→      return "layout-dashboard";
   704→    default:
   705→      return href.split("/").filter(Boolean).pop() ?? "file";
   706→  }
   707→}
   708→
   709→interface WorkspaceNavItemComponentProps {
   710→  item: WorkspaceNavItem;
   711→  workspaceId: string;
   712→  collapsed: boolean;
   713→  onNavigate?: (workspaceId: string, viewPath: string, viewName: string, icon: IconData) => void;
   714→}
   715→
   716→function WorkspaceNavItemComponent({ item, workspaceId, collapsed, onNavigate }: WorkspaceNavItemComponentProps) {
   717→  const { t } = useTranslation();
   718→  const location = useLocation();
   719→  const title = t(item.titleKey);
   720→  const href = `/workspace/${workspaceId}/${item.path}`;
   721→  const agentCompatHref = `/workspace/${workspaceId}/agent`;
   722→
   723→  // Check if this item is active
   724→  const isActive =
   725→    location.pathname === href ||
   726→    location.pathname.startsWith(href + "/") ||
   727→    (item.path === "agents" &&
   728→      (location.pathname === agentCompatHref ||
   729→        location.pathname.startsWith(agentCompatHref + "/")));
   730→
   731→  // Use item path as icon name
   732→  const iconName = item.path;
   733→
   734→  const handleClick = () => {
   735→    if (onNavigate) {
   736→      onNavigate(workspaceId, item.path, title, { type: "lucide", value: iconName });
   737→    }
   738→  };
   739→
   740→  // Collapsed view - use unified SidebarIconButton component with centering wrapper
   741→  if (collapsed) {
   742→    return (
   743→      <div className="grid place-items-center w-full">
   744→        <SidebarIconButton
   745→          icon={<item.icon className="h-4 w-4" />}
   746→          tooltip={title}
   747→          onClick={handleClick}
   748→        />
   749→      </div>
   750→    );
   751→  }
   752→
   753→  // Expanded view - full button with text
   754→  return (
   755→    <button
   756→      type="button"
   757→      onClick={handleClick}
   758→      className={cn(
   759→        "group relative flex items-center gap-3 px-2 py-2 rounded-lg text-sm w-full text-left",
   760→        "transition-all duration-200",
   761→        isActive
   762→          ? [
   763→              "bg-sidebar-accent text-sidebar-accent-foreground font-medium",
   764→              "before:absolute before:left-0 before:top-1/2 before:-translate-y-1/2",
   765→              "before:h-6 before:w-1 before:rounded-r-full before:bg-primary",
   766→            ]
   767→          : [
