    99→
   100→type WorkspaceSectionDropdownBuilder = (
   101→  input: WorkspaceSectionDropdownInput
   102→) => BreadcrumbDropdownItem[];
   103→
   104→function buildDropdownItems<T>(
   105→  items: T[],
   106→  mapItem: (item: T, index: number) => BreadcrumbDropdownItem | null | undefined
   107→): BreadcrumbDropdownItem[] {
   108→  return items
   109→    .map((item, index) => mapItem(item, index))
   110→    .filter((item): item is BreadcrumbDropdownItem => Boolean(item));
   111→}
   112→
   113→export function stackToDesktopSegments(
   114→  stack: BreadcrumbStackItem[] | undefined
   115→): DesktopBreadcrumbSegment[] {
   116→  if (!stack || stack.length <= 1) {
   117→    return [];
   118→  }
   119→
   120→  return stack.slice(1).map((item) => ({
   121→    id: item.id,
   122→    label: item.label,
   123→    href: item.href,
   124→    icon: item.icon,
   125→    descriptorId: item.descriptorId,
   126→    meta: item.meta,
   127→  }));
   128→}
   129→
   130→export function buildFallbackDesktopSegment(input: {
   131→  id: string;
   132→  label: string;
   133→  href: string;
   134→  descriptorId: string;
   135→  icon?: IconData;
   136→  meta?: DesktopBreadcrumbSegment["meta"];
   137→}): DesktopBreadcrumbSegment {
   138→  const item = createBreadcrumbItem({
   139→    id: input.id,
   140→    label: input.label,
   141→    href: input.href,
   142→    descriptorId: input.descriptorId,
   143→    icon: input.icon,
   144→    meta: input.meta,
   145→  });
   146→
   147→  return {
   148→    id: item.id,
   149→    label: item.label,
   150→    href: item.href,
   151→    icon: item.icon,
   152→    descriptorId: item.descriptorId,
   153→    meta: item.meta,
   154→  };
   155→}
   156→
   157→export function buildWorkspaceSectionHeaderSegment(
   158→  workspaceId: string,
   159→  section: WorkspaceSection,
   160→  buildLabel?: (titleKey: string, fallbackLabel: string) => string
   161→): DesktopBreadcrumbSegment {
   162→  const info = getWorkspaceSectionDescriptor(section);
   163→  const routePath = section;
   164→
   165→  return {
   166→    id: `workspace:${workspaceId}:${section}`,
   167→    label: info
   168→      ? buildLabel?.(info.titleKey, info.fallbackLabel) ??
   169→        info.fallbackLabel
   170→      : section,
   171→    href: `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`,
   172→    icon: info?.icon,
   173→    descriptorId: `workspace-section:${section}`,
   174→    meta: {
   175→      workspaceId,
   176→      section,
   177→      routePath,
   178→    },
   179→  };
   180→}
   181→
   182→export function resolveHeaderSegments(input: {
   183→  stack?: BreadcrumbStackItem[];
   184→  fallback?: DesktopBreadcrumbSegment[];
   185→  patchLast?: Partial<DesktopBreadcrumbSegment> & {
   186→    meta?: DesktopBreadcrumbSegment["meta"];
   187→  };
   188→}): DesktopBreadcrumbSegment[] {
   189→  const stackSegments = stackToDesktopSegments(input.stack);
   190→  const patchLast = input.patchLast;
   191→
   192→  if (stackSegments.length === 0) {
   193→    return input.fallback ?? [];
   194→  }
   195→
   196→  if (!patchLast) {
   197→    return stackSegments;
   198→  }
   199→
   200→  return stackSegments.map((segment, index, segments) =>
   201→    index === segments.length - 1
   202→      ? {
   203→          ...segment,
   204→          ...patchLast,
   205→          meta: {
   206→            ...segment.meta,
   207→            ...patchLast.meta,
   208→          },
   209→        }
   210→      : segment
   211→  );
   212→}
   213→
   214→export function createWorkspaceRootNode(
   215→  workspaceId: string,
   216→  label = "Workspace"
   217→): VirtualPageIndexNode {
   218→  return {
   219→    id: `workspace:${workspaceId}`,
   220→    descriptorId: "workspace",
   221→    label,
   222→    icon: { type: "lucide", value: "folder-open" },
   223→    order: 0,
   224→    isContainer: true,
   225→  };
   226→}
   227→
   228→export function createStaticWorkspaceIndexNodes(
   229→  workspaceId: string
   230→): VirtualPageIndexNode[] {
   231→  const root = createWorkspaceRootNode(workspaceId);
   232→  const sectionNodes = WORKSPACE_SECTIONS.map((info, index) => ({
   233→    id: `${root.id}:${info.section}`,
   234→    descriptorId: `workspace-section:${info.section}`,
   235→    label: info.fallbackLabel,
   236→    icon: info.icon,
   237→    parentId: root.id,
   238→    order: index + 1,
   239→    href: `/workspace/${encodeURIComponent(workspaceId)}/${info.section}`,
   240→  }));
   241→
   242→  return [root, ...sectionNodes];
   243→}
   244→
   245→export function resolveSegmentDescriptorId(
   246→  segment: DesktopBreadcrumbSegment
   247→): string | undefined {
   248→  if (segment.descriptorId) {
   249→    return segment.descriptorId;
   250→  }
   251→
   252→  if (/^\/workspace\/[^/]+$/.test(segment.href)) {
   253→    return "workspace";
   254→  }
   255→
   256→  const sectionMatch = segment.href.match(
   257→    /^\/workspace\/[^/]+\/(chat|kanban|cron|ideas|files|github|chat-monitor)$/
   258→  );
   259→  if (sectionMatch) {
   260→    return `workspace-section:${sectionMatch[1]}`;
   261→  }
   262→
   263→  if (/^\/workspace\/[^/]+\/(agent|agents)$/.test(segment.href)) {
   264→    return "workspace-section:agent";
   265→  }
   266→
   267→  if (/^\/agent\/[^/]+/.test(segment.href)) {
   268→    return "workspace-agent";
   269→  }
   270→
   271→  if (/^\/executor\/[^/]+/.test(segment.href)) {
   272→    return "workspace-executor";
   273→  }
   274→
   275→  return undefined;
   276→}
   277→
   278→export function buildRootDropdownItems({
   279→  workspaces = [],
   280→  currentArea = "home",
   281→  activeWorkspaceId,
   282→  currentSection,
   283→  activeHref,
   284→  buildLabel,
   285→  onSelectWorkspace,
   286→  labelGlobalWorkspace,
   287→}: {
   288→  workspaces?: WorkspaceListItemLike[];
   289→  currentArea?: "home" | "pages" | "section";
   290→  activeWorkspaceId?: string;
   291→  currentSection?: WorkspaceSection;
   292→  activeHref?: string;
   293→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   294→  onSelectWorkspace?: (workspaceId: string) => void;
   295→  labelGlobalWorkspace?: string;
   296→}): BreadcrumbDropdownItem[] {
   297→  const sectionRoutePath = currentSection
   298→    ? getWorkspaceSectionRoutePath(currentSection)
   299→    : "";
   300→
   301→  const workspaceItems = buildDropdownItems(workspaces, (workspace) => {
   302→    const workspaceLabel =
   303→      workspace.type === "global"
   304→        ? labelGlobalWorkspace ??
   305→          buildLabel?.("workspace.global", "Global Workspace") ??
   306→          "Global Workspace"
   307→        : workspace.name;
   308→    const href =
   309→      currentArea === "pages"
   310→        ? `/workspace/${encodeURIComponent(workspace.id)}/pages`
   311→        : sectionRoutePath
   312→          ? `/workspace/${encodeURIComponent(workspace.id)}/${sectionRoutePath}`
   313→          : `/workspace/${encodeURIComponent(workspace.id)}`;
   314→
   315→    return {
   316→      id: `workspace:${workspace.id}`,
   317→      label: workspaceLabel,
   318→      href,
   319→      description: workspace.path,
   320→      icon: {
   321→        type: "lucide",
   322→        value: workspace.type === "global" ? "globe" : "folder-open",
   323→      } as IconData,
   324→      isActive: workspace.id === activeWorkspaceId,
   325→      descriptorId: "workspace",
   326→      meta: {
   327→        workspaceId: workspace.id,
   328→        section: currentSection,
   329→        routePath: sectionRoutePath || undefined,
   330→      },
   331→      onSelect: onSelectWorkspace
   332→        ? () => onSelectWorkspace(workspace.id)
   333→        : undefined,
   334→    };
   335→  });
   336→
   337→  const systemItems = buildDropdownItems(
   338→    [
   339→      {
   340→        id: "root:settings",
   341→        label: getSettingsSectionLabel(),
   342→        href: "/settings/general",
   343→        icon: getSettingsSectionIcon(),
   344→        isActive: activeHref?.startsWith("/settings") ?? false,
   345→      },
   346→      {
   347→        id: "root:documents",
   348→        label: buildLabel?.("nav.documents", "Documents") ?? "Documents",
   349→        href: "/documents",
   350→        icon: { type: "lucide", value: "file-text" } as IconData,
   351→        isActive: activeHref === "/documents",
   352→      },
   353→      {
   354→        id: "root:devices",
   355→        label: buildLabel?.("nav.devices", "Devices") ?? "Devices",
   356→        href: "/devices/pair",
   357→        icon: { type: "lucide", value: "smartphone" } as IconData,
   358→        isActive: activeHref === "/devices/pair",
   359→      },
   360→    ],
   361→    (item) => ({
   362→      ...item,
   363→      descriptorId: item.id.replace("root:", ""),
   364→    })
   365→  );
   366→
   367→  return [...workspaceItems, ...systemItems];
   368→}
