   590→export function resolvePageIndexBranch({
   591→  segment,
   592→  workspaceId,
   593→  workspaces,
   594→  pages,
   595→  activeWorkspaceId,
   596→  currentSection,
   597→  currentArea,
   598→  currentPageSlug,
   599→  currentSettingsSection,
   600→  allowGithub,
   601→  buildLabel,
   602→  onSelectWorkspace,
   603→  onSelectSection,
   604→  labelGlobalWorkspace,
   605→}: ResolvePageIndexBranchInput): BreadcrumbDropdownItem[] {
   606→  const descriptorId = resolveSegmentDescriptorId(segment);
   607→
   608→  // Resolve dropdownCategory from route registry when possible.
   609→  // This enables registry-driven dropdown dispatch alongside legacy descriptorId matching.
   610→  // Future: use dropdownCategory to replace descriptorId-based rule matching entirely.
   611→  const routeMatch = segment.href && segment.href !== "#"
   612→    ? registry.match(segment.href)
   613→    : null;
   614→  void routeMatch?.entry.dropdownCategory;
   615→
   616→  const input: ResolvePageIndexBranchInput = {
   617→    segment,
   618→    workspaceId,
   619→    workspaces,
   620→    pages,
   621→    activeWorkspaceId,
   622→    currentSection,
   623→    currentArea,
   624→    currentPageSlug,
   625→    currentSettingsSection,
   626→    allowGithub,
   627→    buildLabel,
   628→    onSelectWorkspace,
   629→    onSelectSection,
   630→    labelGlobalWorkspace,
   631→  };
   632→
   633→  const rules: BreadcrumbDropdownRule[] = [
   634→    {
   635→      matches: (_input, descriptorId) => descriptorId === "workspace",
   636→      build: (input) =>
   637→        buildRootDropdownItems({
   638→          workspaces: input.workspaces,
   639→          currentArea: input.currentArea,
   640→          activeWorkspaceId: input.activeWorkspaceId,
   641→          currentSection: input.currentSection,
   642→          activeHref: input.segment.href,
   643→          buildLabel: input.buildLabel,
   644→          onSelectWorkspace: input.onSelectWorkspace,
   645→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   646→        }),
   647→    },
   648→    {
   649→      matches: (input, descriptorId) =>
   650→        (descriptorId === "virtual-folder" || descriptorId === "settings") &&
   651→        input.segment.href.startsWith("/settings/") &&
   652→        input.segment.label === getSettingsSectionLabel(),
   653→      build: (input) =>
   654→        buildRootDropdownItems({
   655→          workspaces: input.workspaces,
   656→          currentArea: input.currentArea,
   657→          activeWorkspaceId: input.activeWorkspaceId,
   658→          currentSection: input.currentSection,
   659→          activeHref: input.segment.href,
   660→          buildLabel: input.buildLabel,
   661→          onSelectWorkspace: input.onSelectWorkspace,
   662→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   663→        }),
   664→    },
   665→    {
   666→      matches: (input, descriptorId) =>
   667→        (descriptorId === "virtual-folder" || descriptorId === "workspace-section:pages") &&
   668→        Boolean(input.segment.meta?.workspaceId) &&
   669→        input.segment.href ===
   670→          `/workspace/${encodeURIComponent(input.segment.meta?.workspaceId ?? "")}/pages`,
   671→      build: (input) =>
   672→        buildWorkspacePagesDropdownItems({
   673→          workspaceId: input.segment.meta?.workspaceId ?? "",
   674→          activeSection: "pages",
   675→          buildLabel: input.buildLabel,
   676→          onSelectSection: input.onSelectSection,
   677→          allowGithub: input.allowGithub,
   678→          pages: input.pages,
   679→          currentPageSlug: input.currentPageSlug,
   680→        }),
   681→    },
   682→    {
   683→      matches: (input, descriptorId) =>
   684→        Boolean(descriptorId?.startsWith("settings")) &&
   685→        input.segment.href.startsWith("/settings/"),
   686→      build: (input) =>
   687→        buildSettingsDropdownItems({
   688→          activeSection:
   689→            input.segment.href.split("/settings/")[1] ||
   690→            input.currentSettingsSection ||
   691→            "general",
   692→          buildLabel: input.buildLabel,
   693→        }),
   694→    },
   695→    {
   696→      matches: (input, descriptorId) =>
   697→        Boolean(descriptorId?.startsWith("workspace-section:")) &&
   698→        Boolean(input.workspaceId ?? input.segment.meta?.workspaceId),
   699→      build: (input) => {
   700→        const section = input.segment.meta?.section ?? input.currentSection ?? "chat";
   701→        return buildWorkspaceSectionDropdownItems(section, {
   702→          workspaceId: input.workspaceId ?? input.segment.meta?.workspaceId ?? "",
   703→          activeSection: section,
   704→          buildLabel: input.buildLabel,
   705→          onSelectSection: input.onSelectSection,
   706→          allowGithub: input.allowGithub,
   707→        });
   708→      },
   709→    },
   710→    {
   711→      matches: (input, descriptorId) =>
   712→        descriptorId === "workspace-page" &&
   713→        Boolean(input.segment.meta?.pageSlug) &&
   714→        Boolean(input.pages?.length),
   715→      build: (input) => {
   716→        const wId = input.workspaceId ?? input.segment.meta?.workspaceId ?? "";
   717→        const currentSlug = input.segment.meta?.pageSlug ?? "";
   718→        // Find parent prefix to get siblings
   719→        const parentPrefix = currentSlug.includes("/")
   720→          ? currentSlug.slice(0, currentSlug.lastIndexOf("/") + 1)
   721→          : "";
   722→        const depth = parentPrefix ? parentPrefix.split("/").filter(Boolean).length + 1 : 1;
   723→
   724→        const siblings = (input.pages ?? []).filter((page) => {
   725→          // Same depth and same parent prefix
   726→          const pageDepth = page.slug.split("/").filter(Boolean).length;
   727→          if (pageDepth !== depth) return false;
   728→          if (parentPrefix) {
   729→            return page.slug.startsWith(parentPrefix);
   730→          }
   731→          return !page.slug.includes("/");
   732→        });
   733→
   734→        return buildDropdownItems(siblings, (page) => ({
   735→          id: `workspace:${wId}:page:${page.slug}`,
   736→          label: page.name,
   737→          href: `/workspace/${encodeURIComponent(wId)}/page/${page.slug
   738→            .split("/")
   739→            .filter(Boolean)
   740→            .map((s) => encodeURIComponent(s))
   741→            .join("/")}`,
   742→          icon: page.icon,
   743→          isActive: page.slug === currentSlug,
   744→          descriptorId: "workspace-page",
   745→          meta: {
   746→            workspaceId: wId,
   747→            pageSlug: page.slug,
   748→          },
   749→        }));
   750→      },
   751→    },
   752→  ];
   753→
   754→  const matchedRule = rules.find((rule) => rule.matches(input, descriptorId));
   755→
   756→  if (matchedRule) {
   757→    return matchedRule.build(input);
   758→  }
   759→
   760→  return [];
   761→}
