   553→  return useMemo(
   554→    () => ({
   555→      tabs,
   556→      ...activeState,
   557→      ...actions,
   558→      ...navigation,
   559→    }),
   560→    [tabs, activeState, actions, navigation]
   561→  );
   562→}
   563→
   564→// ─── Utilities ──────────────────────────────────────────────────────────────
   565→
   566→function safeHostname(url: string): string {
   567→  try {
   568→    return new URL(url).hostname;
   569→  } catch {
   570→    return url;
   571→  }
   572→}
