              {item.label}
            </ContextMenuItem>
          ))
        ) : (
          <ContextMenuItem disabled>
            {t("tabBar.noBackHistory", "No back history")}
          </ContextMenuItem>
        )}
      </ContextMenuContent>
    </ContextMenu>

    {/* Forward button */}
    <ContextMenu>
      <Tooltip>
        <TooltipTrigger asChild>
          <ContextMenuTrigger asChild>
            <Button
