     1→/**
     2→ * IconDisplay Component
     3→ *
     4→ * Unified icon display component that supports:
     5→ * - Lucide icons (by name)
     6→ * - Emoji characters
     7→ * - Custom images (local path or URL)
     8→ */
     9→
    10→import { useState, useMemo, useEffect } from "react";
    11→import { FileText } from "lucide-react";
    12→import { cn } from "@/lib/utils";
    13→import { DynamicLucideIcon } from "./dynamic-lucide-icon";
    14→import { LUCIDE_ICON_MAP, DEFAULT_ICON_NAME } from "./constants";
    15→import { parseIconData, getIconSizeClass, getIconPixelSize } from "./utils";
    16→import type { IconData, IconSize } from "./types";
    17→
    18→export interface IconDisplayProps {
    19→  /** Icon data (new format) or string (old format) */
    20→  icon?: IconData | string | null;
    21→  /** Icon size preset or pixel value */
    22→  size?: IconSize | number;
    23→  /** Fallback icon when icon is empty or invalid */
    24→  fallback?: IconData | string;
    25→  /** Workspace path for resolving relative image paths */
    26→  workspacePath?: string;
    27→  /** Additional CSS classes */
    28→  className?: string;
    29→  /** Alt text for images */
    30→  alt?: string;
    31→}
    32→
    33→/**
    34→ * Internal component for rendering image icons
    35→ */
    36→function ImageIcon({
    37→  src,
    38→  size,
    39→  workspacePath,
    40→  className,
    41→  alt,
    42→}: {
    43→  src: string;
    44→  size: number;
    45→  workspacePath?: string;
    46→  className?: string;
    47→  alt?: string;
    48→}) {
    49→  const [error, setError] = useState(false);
    50→  const [loading, setLoading] = useState(true);
    51→
    52→  // Resolve the image URL
    53→  const imageUrl = useMemo(() => {
    54→    // Already a full URL or data URL
    55→    if (src.startsWith("http://") || src.startsWith("https://") || src.startsWith("data:")) {
    56→      return src;
    57→    }
    58→
    59→    // Relative path - need to construct URL through gateway
    60→    if (workspacePath) {
    61→      // Use gateway file serving endpoint
    62→      const gatewayUrl = import.meta.env.VITE_GATEWAY_URL || "http://127.0.0.1:18790";
    63→      return `${gatewayUrl}/api/file/read?workspace_path=${encodeURIComponent(workspacePath)}&file_path=${encodeURIComponent(src)}`;
    64→    }
    65→
    66→    // Fallback: treat as relative path (may not work without workspace)
    67→    return src;
    68→  }, [src, workspacePath]);
    69→
    70→  // Reset states when src changes
    71→  useEffect(() => {
    72→    setError(false);
    73→    setLoading(true);
    74→  }, [imageUrl]);
    75→
    76→  if (error) {
    77→    // Show fallback icon on error
    78→    return <FileText className={cn(getIconSizeClass(size), className)} />;
    79→  }
    80→
    81→  return (
    82→    <span
    83→      className={cn(
    84→        "inline-flex items-center justify-center overflow-hidden rounded",
    85→        className
    86→      )}
    87→      style={{ width: size, height: size }}
    88→    >
    89→      {loading && (
    90→        <span
    91→          className="animate-pulse bg-muted rounded"
    92→          style={{ width: size, height: size }}
    93→        />
    94→      )}
    95→      <img
    96→        src={imageUrl}
    97→        alt={alt ?? "icon"}
    98→        width={size}
    99→        height={size}
   100→        className={cn(
   101→          "object-cover",
   102→          loading && "hidden"
   103→        )}
   104→        onLoad={() => setLoading(false)}
   105→        onError={() => {
   106→          setLoading(false);
   107→          setError(true);
   108→        }}
   109→      />
   110→    </span>
   111→  );
   112→}
   113→
   114→/**
   115→ * IconDisplay component
   116→ *
   117→ * Renders an icon based on its type (lucide, emoji, or image).
   118→ * Supports both new IconData format and legacy string format.
   119→ */
   120→export function IconDisplay({
   121→  icon,
   122→  size = "md",
   123→  fallback,
   124→  workspacePath,
   125→  className,
   126→  alt,
   127→}: IconDisplayProps) {
   128→  // Parse icon data from various formats
   129→  const iconData = useMemo(() => {
   130→    // Parse the main icon
   131→    let data: IconData | null = null;
   132→
   133→    if (icon) {
   134→      if (typeof icon === "string") {
   135→        data = parseIconData(icon);
   136→      } else {
   137→        data = icon;
   138→      }
   139→    }
   140→
   141→    // Use fallback if no valid icon
   142→    if (!data && fallback) {
   143→      if (typeof fallback === "string") {
   144→        data = parseIconData(fallback);
   145→      } else {
   146→        data = fallback;
   147→      }
   148→    }
   149→
   150→    // Ultimate fallback
   151→    if (!data) {
   152→      data = { type: "lucide", value: DEFAULT_ICON_NAME };
   153→    }
   154→
   155→    return data;
   156→  }, [icon, fallback]);
   157→
   158→  // Get size values
   159→  const sizeClass = getIconSizeClass(size);
   160→  const pixelSize = getIconPixelSize(size);
   161→
   162→  // Render based on icon type
   163→  switch (iconData.type) {
   164→    case "lucide": {
   165→      const StaticIcon = LUCIDE_ICON_MAP[iconData.value];
   166→      if (StaticIcon) {
   167→        return <StaticIcon className={cn(sizeClass, "shrink-0", className)} />;
   168→      }
   169→      // Fallback: dynamically load icons not in static map
   170→      return (
   171→        <DynamicLucideIcon
   172→          name={iconData.value}
