     1→import type { IconData } from "@/components/ui/icon-picker";
     2→import type { BreadcrumbStackItem } from "./breadcrumb-builder";
     3→import type {
     4→  VirtualPageIndexNode,
     5→  WorkspaceSection,
     6→} from "./navigation-meta";
     7→import {
     8→  SETTINGS_SECTIONS,
     9→  getWorkspaceSectionDescriptor,
    10→  getWorkspaceSectionRoutePath,
    11→  WORKSPACE_SECTIONS,
    12→  getSettingsSectionIcon,
    13→  getSettingsSectionLabel,
    14→} from "./navigation-meta";
    15→import { createBreadcrumbItem } from "./breadcrumb-stack";
    16→import { registry } from "./route-registry";
    17→import type { PageConfig } from "@/hooks/use-pages";
    18→export { getWorkspaceSectionDescriptor } from "./navigation-meta";
    19→
    20→export interface DesktopBreadcrumbSegment {
    21→  id?: string;
    22→  label: string;
    23→  titleKey?: string;
    24→  href: string;
    25→  path?: string;
    26→  onClick?: () => void;
    27→  icon?: IconData;
    28→  descriptorId?: string;
    29→  meta?: {
    30→    workspaceId?: string;
    31→    section?: WorkspaceSection;
    32→    routePath?: string;
    33→    pageSlug?: string;
    34→    agentId?: string;
    35→    executorType?: string;
    36→    webId?: string;
    37→    url?: string;
    38→    blockId?: string;
    39→  };
    40→}
    41→
    42→export interface BreadcrumbDropdownItem {
    43→  id: string;
    44→  label: string;
    45→  href?: string;
    46→  icon?: IconData;
    47→  description?: string;
    48→  separator?: boolean;
    49→  onSelect?: () => void;
    50→  isActive?: boolean;
    51→  descriptorId?: string;
    52→  meta?: DesktopBreadcrumbSegment["meta"];
    53→}
    54→
    55→export interface WorkspaceListItemLike {
    56→  id: string;
    57→  name: string;
    58→  path?: string;
    59→  type?: string;
    60→}
    61→
    62→export interface ResolvePageIndexBranchInput {
    63→  segment: DesktopBreadcrumbSegment;
    64→  workspaceId?: string;
    65→  workspaces?: WorkspaceListItemLike[];
    66→  pages?: PageConfig[];
    67→  activeWorkspaceId?: string;
    68→  currentSection?: WorkspaceSection;
    69→  currentArea?: "home" | "pages" | "section";
    70→  currentPageSlug?: string;
    71→  currentSettingsSection?: string;
    72→  allowGithub?: boolean;
    73→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
    74→  onSelectWorkspace?: (workspaceId: string) => void;
    75→  onSelectSection?: (
    76→    section: WorkspaceSection,
    77→    routePath: string,
    78→    href: string
    79→  ) => void;
    80→  labelGlobalWorkspace?: string;
    81→}
    82→
    83→interface BreadcrumbDropdownRule {
    84→  matches: (input: ResolvePageIndexBranchInput, descriptorId: string | undefined) => boolean;
    85→  build: (input: ResolvePageIndexBranchInput) => BreadcrumbDropdownItem[];
    86→}
    87→
    88→interface WorkspaceSectionDropdownInput {
    89→  workspaceId: string;
    90→  activeSection?: WorkspaceSection;
    91→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
    92→  onSelectSection?: (
    93→    section: WorkspaceSection,
    94→    routePath: string,
    95→    href: string
    96→  ) => void;
    97→  allowGithub?: boolean;
    98→}
    99→
   100→type WorkspaceSectionDropdownBuilder = (
   101→  input: WorkspaceSectionDropdownInput
   102→) => BreadcrumbDropdownItem[];
   103→
   104→function buildDropdownItems<T>(
   105→  items: T[],
   106→  mapItem: (item: T, index: number) => BreadcrumbDropdownItem | null | undefined
   107→): BreadcrumbDropdownItem[] {
   108→  return items
   109→    .map((item, index) => mapItem(item, index))
   110→    .filter((item): item is BreadcrumbDropdownItem => Boolean(item));
   111→}
   112→
   113→export function stackToDesktopSegments(
   114→  stack: BreadcrumbStackItem[] | undefined
   115→): DesktopBreadcrumbSegment[] {
   116→  if (!stack || stack.length <= 1) {
   117→    return [];
   118→  }
   119→
   120→  return stack.slice(1).map((item) => ({
   121→    id: item.id,
   122→    label: item.label,
   123→    href: item.href,
   124→    icon: item.icon,
   125→    descriptorId: item.descriptorId,
   126→    meta: item.meta,
   127→  }));
   128→}
   129→
   130→export function buildFallbackDesktopSegment(input: {
   131→  id: string;
   132→  label: string;
   133→  href: string;
   134→  descriptorId: string;
   135→  icon?: IconData;
   136→  meta?: DesktopBreadcrumbSegment["meta"];
   137→}): DesktopBreadcrumbSegment {
   138→  const item = createBreadcrumbItem({
   139→    id: input.id,
   140→    label: input.label,
   141→    href: input.href,
   142→    descriptorId: input.descriptorId,
   143→    icon: input.icon,
   144→    meta: input.meta,
   145→  });
   146→
   147→  return {
   148→    id: item.id,
   149→    label: item.label,
   150→    href: item.href,
   151→    icon: item.icon,
   152→    descriptorId: item.descriptorId,
   153→    meta: item.meta,
   154→  };
   155→}
   156→
   157→export function buildWorkspaceSectionHeaderSegment(
   158→  workspaceId: string,
   159→  section: WorkspaceSection,
   160→  buildLabel?: (titleKey: string, fallbackLabel: string) => string
   161→): DesktopBreadcrumbSegment {
   162→  const info = getWorkspaceSectionDescriptor(section);
   163→  const routePath = section;
   164→
   165→  return {
   166→    id: `workspace:${workspaceId}:${section}`,
   167→    label: info
   168→      ? buildLabel?.(info.titleKey, info.fallbackLabel) ??
   169→        info.fallbackLabel
   170→      : section,
   171→    href: `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`,
   172→    icon: info?.icon,
   173→    descriptorId: `workspace-section:${section}`,
   174→    meta: {
   175→      workspaceId,
   176→      section,
   177→      routePath,
   178→    },
   179→  };
   180→}
   181→
   182→export function resolveHeaderSegments(input: {
   183→  stack?: BreadcrumbStackItem[];
   184→  fallback?: DesktopBreadcrumbSegment[];
   185→  patchLast?: Partial<DesktopBreadcrumbSegment> & {
   186→    meta?: DesktopBreadcrumbSegment["meta"];
   187→  };
   188→}): DesktopBreadcrumbSegment[] {
   189→  const stackSegments = stackToDesktopSegments(input.stack);
   190→  const patchLast = input.patchLast;
   191→
   192→  if (stackSegments.length === 0) {
   193→    return input.fallback ?? [];
   194→  }
   195→
   196→  if (!patchLast) {
   197→    return stackSegments;
   198→  }
   199→
   200→  return stackSegments.map((segment, index, segments) =>
   201→    index === segments.length - 1
   202→      ? {
   203→          ...segment,
   204→          ...patchLast,
   205→          meta: {
   206→            ...segment.meta,
   207→            ...patchLast.meta,
   208→          },
   209→        }
   210→      : segment
   211→  );
   212→}
   213→
   214→export function createWorkspaceRootNode(
   215→  workspaceId: string,
   216→  label = "Workspace"
   217→): VirtualPageIndexNode {
   218→  return {
   219→    id: `workspace:${workspaceId}`,
   220→    descriptorId: "workspace",
   221→    label,
   222→    icon: { type: "lucide", value: "folder-open" },
   223→    order: 0,
   224→    isContainer: true,
   225→  };
   226→}
   227→
   228→export function createStaticWorkspaceIndexNodes(
   229→  workspaceId: string
   230→): VirtualPageIndexNode[] {
   231→  const root = createWorkspaceRootNode(workspaceId);
   232→  const sectionNodes = WORKSPACE_SECTIONS.map((info, index) => ({
   233→    id: `${root.id}:${info.section}`,
   234→    descriptorId: `workspace-section:${info.section}`,
   235→    label: info.fallbackLabel,
   236→    icon: info.icon,
   237→    parentId: root.id,
   238→    order: index + 1,
   239→    href: `/workspace/${encodeURIComponent(workspaceId)}/${info.section}`,
   240→  }));
   241→
