   603→export function resolvePageIndexBranch({
   604→  segment,
   605→  workspaceId,
   606→  workspaces,
   607→  pages,
   608→  activeWorkspaceId,
   609→  currentSection,
   610→  currentArea,
   611→  currentPageSlug,
   612→  currentSettingsSection,
   613→  allowGithub,
   614→  buildLabel,
   615→  onSelectWorkspace,
   616→  onSelectSection,
   617→  labelGlobalWorkspace,
   618→}: ResolvePageIndexBranchInput): BreadcrumbDropdownItem[] {
   619→  const descriptorId = resolveSegmentDescriptorId(segment);
   620→
   621→  // Resolve dropdownCategory from route registry when possible.
   622→  // This enables registry-driven dropdown dispatch alongside legacy descriptorId matching.
   623→  // Future: use dropdownCategory to replace descriptorId-based rule matching entirely.
   624→  const routeMatch = segment.href && segment.href !== "#"
   625→    ? registry.match(segment.href)
   626→    : null;
   627→  void routeMatch?.entry.dropdownCategory;
   628→
   629→  const input: ResolvePageIndexBranchInput = {
   630→    segment,
   631→    workspaceId,
   632→    workspaces,
   633→    pages,
   634→    activeWorkspaceId,
   635→    currentSection,
   636→    currentArea,
   637→    currentPageSlug,
   638→    currentSettingsSection,
   639→    allowGithub,
   640→    buildLabel,
   641→    onSelectWorkspace,
   642→    onSelectSection,
   643→    labelGlobalWorkspace,
   644→  };
   645→
   646→  const rules: BreadcrumbDropdownRule[] = [
   647→    {
   648→      matches: (_input, descriptorId) => descriptorId === "workspace",
   649→      build: (input) =>
   650→        buildRootDropdownItems({
   651→          workspaces: input.workspaces,
   652→          currentArea: input.currentArea,
   653→          activeWorkspaceId: input.activeWorkspaceId,
   654→          currentSection: input.currentSection,
   655→          activeHref: input.segment.href,
   656→          buildLabel: input.buildLabel,
   657→          onSelectWorkspace: input.onSelectWorkspace,
   658→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   659→        }),
   660→    },
   661→    {
   662→      matches: (input, descriptorId) =>
   663→        (descriptorId === "virtual-folder" || descriptorId === "settings") &&
   664→        input.segment.href.startsWith("/settings/") &&
   665→        input.segment.label === getSettingsSectionLabel(),
   666→      build: (input) =>
   667→        buildRootDropdownItems({
   668→          workspaces: input.workspaces,
   669→          currentArea: input.currentArea,
   670→          activeWorkspaceId: input.activeWorkspaceId,
   671→          currentSection: input.currentSection,
   672→          activeHref: input.segment.href,
   673→          buildLabel: input.buildLabel,
   674→          onSelectWorkspace: input.onSelectWorkspace,
   675→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   676→        }),
   677→    },
   678→    {
   679→      matches: (input, descriptorId) =>
   680→        descriptorId === "settings" &&
   681→        input.segment.href === "/settings",
   682→      build: (input) =>
   683→        buildRootDropdownItems({
   684→          workspaces: input.workspaces,
   685→          currentArea: input.currentArea,
   686→          activeWorkspaceId: input.activeWorkspaceId,
   687→          currentSection: input.currentSection,
   688→          activeHref: input.segment.href,
   689→          buildLabel: input.buildLabel,
   690→          onSelectWorkspace: input.onSelectWorkspace,
   691→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   692→        }),
   693→    },
   694→    {
   695→      matches: (input, descriptorId) =>
   696→        (descriptorId === "virtual-folder" || descriptorId === "workspace-section:pages") &&
   697→        Boolean(input.segment.meta?.workspaceId) &&
   698→        input.segment.href ===
   699→          `/workspace/${encodeURIComponent(input.segment.meta?.workspaceId ?? "")}/pages`,
   700→      build: (input) =>
   701→        buildWorkspacePagesDropdownItems({
   702→          workspaceId: input.segment.meta?.workspaceId ?? "",
   703→          activeSection: "pages",
   704→          buildLabel: input.buildLabel,
   705→          onSelectSection: input.onSelectSection,
   706→          allowGithub: input.allowGithub,
   707→          pages: input.pages,
   708→          currentPageSlug: input.currentPageSlug,
   709→        }),
   710→    },
   711→    {
   712→      matches: (input, descriptorId) =>
   713→        Boolean(descriptorId?.startsWith("settings")) &&
   714→        input.segment.href.startsWith("/settings/"),
   715→      build: (input) =>
   716→        buildSettingsDropdownItems({
   717→          activeSection:
   718→            input.segment.href.split("/settings/")[1] ||
   719→            input.currentSettingsSection ||
   720→            "general",
   721→          buildLabel: input.buildLabel,
   722→        }),
   723→    },
   724→    {
   725→      matches: (input, descriptorId) =>
   726→        Boolean(descriptorId?.startsWith("workspace-section:")) &&
   727→        Boolean(input.workspaceId ?? input.segment.meta?.workspaceId),
   728→      build: (input) => {
   729→        const descriptorId = resolveSegmentDescriptorId(input.segment);
   730→        const sectionFromDescriptor = descriptorId?.startsWith("workspace-section:")
   731→          ? descriptorId.slice("workspace-section:".length) as WorkspaceSection
   732→          : undefined;
   733→        const section = sectionFromDescriptor ?? input.segment.meta?.section ?? input.currentSection ?? "chat";
   734→        const wId = input.workspaceId ?? input.segment.meta?.workspaceId ?? "";
   735→
   736→        // For pages section, pass pages list for the dropdown
   737→        if (section === "pages") {
   738→          return buildWorkspacePagesDropdownItems({
   739→            workspaceId: wId,
   740→            activeSection: section,
   741→            buildLabel: input.buildLabel,
   742→            onSelectSection: input.onSelectSection,
   743→            allowGithub: input.allowGithub,
   744→            pages: input.pages,
   745→            currentPageSlug: input.currentPageSlug,
   746→          });
   747→        }
   748→
   749→        return buildWorkspaceSectionDropdownItems(section, {
   750→          workspaceId: wId,
   751→          activeSection: section,
   752→          buildLabel: input.buildLabel,
   753→          onSelectSection: input.onSelectSection,
   754→          allowGithub: input.allowGithub,
   755→        });
   756→      },
   757→    },
   758→    {
   759→      matches: (input, descriptorId) =>
   760→        descriptorId === "workspace-page" &&
   761→        Boolean(input.pages?.length),
   762→      build: (input) => {
   763→        const wId = input.workspaceId ?? input.segment.meta?.workspaceId ?? "";
   764→        // Derive slug from meta or href
   765→        const currentSlug = input.segment.meta?.pageSlug ??
   766→          input.segment.href.match(/^\/workspace\/[^/]+\/pages\/(.+)$/)?.[1] ?? "";
   767→        // Find parent prefix to get siblings
   768→        const parentPrefix = currentSlug.includes("/")
   769→          ? currentSlug.slice(0, currentSlug.lastIndexOf("/") + 1)
   770→          : "";
   771→        const depth = parentPrefix ? parentPrefix.split("/").filter(Boolean).length + 1 : 1;
   772→
   773→        const siblings = (input.pages ?? []).filter((page) => {
   774→          // Same depth and same parent prefix
   775→          const pageDepth = page.slug.split("/").filter(Boolean).length;
   776→          if (pageDepth !== depth) return false;
   777→          if (parentPrefix) {
   778→            return page.slug.startsWith(parentPrefix);
   779→          }
   780→          return !page.slug.includes("/");
   781→        });
   782→
   783→        return buildDropdownItems(siblings, (page) => ({
   784→          id: `workspace:${wId}:page:${page.slug}`,
   785→          label: page.name,
   786→          href: `/workspace/${encodeURIComponent(wId)}/pages/${page.slug
   787→            .split("/")
   788→            .filter(Boolean)
   789→            .map((s) => encodeURIComponent(s))
   790→            .join("/")}`,
   791→          icon: page.icon,
   792→          isActive: page.slug === currentSlug,
   793→          descriptorId: "workspace-page",
   794→          meta: {
   795→            workspaceId: wId,
   796→            pageSlug: page.slug,
   797→          },
   798→        }));
   799→      },
   800→    },
   801→  ];
   802→
   803→  const matchedRule = rules.find((rule) => rule.matches(input, descriptorId));
   804→
   805→  if (matchedRule) {
   806→    return matchedRule.build(input);
   807→  }
   808→
   809→  return [];
   810→}
