   175→function safeHostname(url: string): string {
   176→  try {
   177→    return new URL(url).hostname;
   178→  } catch {
   179→    return url;
   180→  }
   181→}
   182→
   183→function inferWorkspaceIdFromUrl(url: string | null): string | null {
   184→  if (!url) return null;
   185→  const match = registry.match(url);
   186→  return match?.params?.workspaceId ?? null;
   187→}
   188→
   189→function buildTabStoreActions(activeTabId: string | null) {
   190→  const store = useTabStore.getState();
   191→  return {
   192→    activeTabId: activeTabId ?? "",
   193→    pushNavigation: store.pushNavigation,
   194→    replaceNavigation: store.replaceNavigation,
   195→    resetNavigation: store.resetNavigation,
   196→  };
   197→}
