  1159→
  1160→  useEffect(() => {
  1161→    setHeaderCenter(centerContent ?? null);
  1162→  }, [centerContent, setHeaderCenter]);
  1163→
  1164→  useEffect(() => {
  1165→    setHeaderRight(rightContent ?? null);
  1166→  }, [rightContent, setHeaderRight]);
  1167→
  1168→  useEffect(() => clearHeaderSlots, [clearHeaderSlots]);
  1169→}
