   144→  return WORKSPACE_SECTION_MAP.get(section);
   145→}
   146→
   147→export function getSettingsSectionDescriptor(section?: string): SettingsSectionInfo | undefined {
   148→  if (!section) return undefined;
   149→  return SETTINGS_SECTION_MAP.get(section);
