   152→// ─── Normalization Functions ─────────────────────────────────────────────────
   153→
   154→function isWorkspaceSection(value: string): value is WorkspaceSection {
   155→  return WORKSPACE_SECTION_MAP.has(value);
   156→}
   157→
   158→function isSettingsSection(value: string): value is SettingsSection {
   159→  return SETTINGS_SECTION_MAP.has(value);
   160→}
   161→
   162→export function normalizeWorkspaceSection(value: string): WorkspaceSection {
   163→  if (value === "agents") return "agent";
   164→  if (value === "apps") return "pages";
   165→  if (isWorkspaceSection(value)) return value;
   166→  return "chat";
   167→}
   168→
   169→export function normalizeSettingsSection(value?: string | null): SettingsSection {
   170→  if (!value) return "general";
   171→  return isSettingsSection(value) ? value : "general";
   172→}
   173→
   174→// ─── Label / Icon Helpers ────────────────────────────────────────────────────
   175→
   176→export function getSettingsSectionLabel(section?: string): string {
   177→  const info = getSettingsSectionDescriptor(section);
   178→  if (!info) return i18n.t("settings.title", "Settings");
   179→  return i18n.t(info.titleKey, info.fallbackLabel);
   180→}
