   182→export function getSettingsSectionIcon(section?: string): IconData {
   183→  return getSettingsSectionDescriptor(section)?.icon ?? { type: "lucide", value: "settings" };
   184→}
   185→
   186→export function getWorkspaceSectionLabel(section?: WorkspaceSection): string {
   187→  const info = getWorkspaceSectionDescriptor(section);
   188→  if (!info) return "";
   189→  return i18n.t(info.titleKey, info.fallbackLabel);
   190→}
   191→
   192→export function getWorkspaceSectionRoutePath(section: WorkspaceSection): string {
   193→  return section;
   194→}
   195→
   196→/** Resolve icon for an item by looking up via route-registry */
   197→export function getDescriptorIcon(descriptorId: string | undefined): IconData | undefined {
   198→  if (!descriptorId) return undefined;
   199→  // Try route-registry pattern lookup
   200→  const icon = registry.getIcon(descriptorId);
   201→  if (icon) return icon;
   202→  // Fallback: check workspace/settings section maps by legacy descriptor id format
   203→  if (descriptorId.startsWith("workspace-section:")) {
   204→    const section = descriptorId.slice("workspace-section:".length);
   205→    return WORKSPACE_SECTION_MAP.get(section)?.icon;
   206→  }
   207→  if (descriptorId.startsWith("settings:")) {
   208→    const section = descriptorId.slice("settings:".length);
   209→    return SETTINGS_SECTION_MAP.get(section)?.icon;
   210→  }
   211→  return undefined;
   212→}
